(function(global){
'use strict';
function evaluateSweep(values){const cents={};for(const key of ['balance','receipts','payments','buffer']){const v=values[key];if(typeof v!=='number'||!Number.isFinite(v)||v<0||v>1e12)throw Error('Enter an amount between zero and one trillion for every field.');cents[key]=Math.round(v*100)}const forecast=cents.balance+cents.receipts-cents.payments,surplus=Math.max(0,forecast-cents.buffer),sweep=Math.min(cents.balance,surplus),gap=Math.max(0,cents.buffer-forecast);return {forecast:forecast/100,sweep:sweep/100,gap:gap/100,after:(forecast-sweep)/100,capped:sweep<surplus};}
global.PortfolioSweep={evaluateSweep};
if(typeof document==='undefined')return;
const form=document.getElementById('sweep-form');if(!form)return;const result=document.getElementById('sweep-result'),error=document.getElementById('sweep-error'),money=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2});
const el=(tag,text,cls)=>{const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;return n};
function render(){error.textContent='';if(!form.reportValidity())return;try{const values={};for(const key of ['balance','receipts','payments','buffer']){const field=form.elements.namedItem(key);if(!field.value.trim())throw Error('Complete every scenario field.');values[key]=field.valueAsNumber}const r=evaluateSweep(values);result.replaceChildren();result.append(el('p','ILLUSTRATIVE PLANNING RESULT','eyebrow'),el('h3',r.gap?'Liquidity needs attention':'Indicative cash-sweep amount'),el('strong',money.format(r.gap?r.gap:r.sweep),'sweep-amount'));result.append(el('p',r.gap?'Projected shortfall against the minimum buffer. No sweep is indicated.':'Available surplus, capped at current cash. A recommendation for treasury review, with no payment initiated.'));const dl=el('dl','','scenario-metrics');for(const [label,value] of [['Forecast cash before sweep',r.forecast],['Minimum liquidity buffer',values.buffer],['Forecast cash after indicated sweep',r.after]])dl.append(el('dt',label),el('dd',money.format(value)));result.append(dl,el('h4','How this was calculated'),el('p','Forecast cash = current cash + expected receipts − expected payments. Indicated sweep = the smaller of current cash and forecast cash above the buffer.'));if(r.capped)result.append(el('p','The indication is capped because forecast receipts are not yet available cash.'));result.append(el('p','Next step: review timing, forecast confidence and policy eligibility with treasury.','review-note'));}catch(e){error.textContent=e.message}}
form.addEventListener('submit',event=>{event.preventDefault();render()});render();
})(typeof window==='undefined'?globalThis:window);
